# Verbetes comuns das Fables (parte 1: palavras gramaticais e frequentes).
# V(chave, lema, classe, forma, defs, nota) — defs separadas por « || »
M = {}
def V(k, lema, classe, forma, defs, nota='', wiki=None):
    d = {'lema': lema, 'classe': classe}
    if wiki is not None:
        d['wiki'] = wiki
    if forma:
        d['forma'] = forma
    d['def'] = [x.strip() for x in defs.split('||')]
    if nota:
        d['nota'] = nota
    M[k] = d

